{
  "id": "547386",
  "schema": "zapp",
  "name": "pii_access_log",
  "rls_enabled": true,
  "size": "24 kB",
  "comment": "Módulo inativo/vazio até 2026-08 (sprawl F-009); ver DICIONARIO",
  "columns": [
    {
      "attnum": 1,
      "attname": "id",
      "type": "uuid",
      "nullable": false,
      "default_value": "gen_random_uuid()"
    },
    {
      "attnum": 2,
      "attname": "accessed_by",
      "type": "uuid",
      "nullable": true,
      "default_value": null
    },
    {
      "attnum": 3,
      "attname": "contact_id",
      "type": "uuid",
      "nullable": true,
      "default_value": null
    },
    {
      "attnum": 4,
      "attname": "field",
      "type": "text",
      "nullable": false,
      "default_value": null
    },
    {
      "attnum": 5,
      "attname": "accessed_at",
      "type": "timestamp with time zone",
      "nullable": false,
      "default_value": "now()"
    },
    {
      "attnum": 6,
      "attname": "source",
      "type": "text",
      "nullable": true,
      "default_value": null
    }
  ],
  "constraints": [
    {
      "conname": "pii_access_log_accessed_by_fkey",
      "type": "FOREIGN KEY",
      "definition": "FOREIGN KEY (accessed_by) REFERENCES auth.users(id)"
    },
    {
      "conname": "pii_access_log_pkey",
      "type": "PRIMARY KEY",
      "definition": "PRIMARY KEY (id)"
    }
  ],
  "indexes": [
    {
      "name": "idx_pii_access_log_user",
      "definition": "CREATE INDEX idx_pii_access_log_user ON zapp.pii_access_log USING btree (accessed_by, accessed_at DESC)",
      "is_unique": false,
      "is_primary": false
    },
    {
      "name": "pii_access_log_pkey",
      "definition": "CREATE UNIQUE INDEX pii_access_log_pkey ON zapp.pii_access_log USING btree (id)",
      "is_unique": true,
      "is_primary": true
    }
  ]
}
